from urllib.parse import urlsplit

def allowed_redirect(url, allowed_host):
    parsed = urlsplit(url)
    if parsed.scheme != "https":
        return False

    # Extract hostname from netloc, ignoring port if present
    # netloc can be 'hostname' or 'hostname:port'
    hostname_from_url = parsed.netloc.split(':')[0]

    # Compare extracted hostname with allowed_host, case-insensitively
    return hostname_from_url.lower() == allowed_host.lower()

