def drain_ready(queue, cutoff):
    ready = []
    remaining_queue = []
    for task in queue:
        if task[1] <= cutoff:
            ready.append(task)
        else:
            remaining_queue.append(task)

    # Modify the original queue in-place
    queue[:] = remaining_queue

    return ready

